// ═══ CAUSE 1: Iterator.next() without hasNext() ═══
List<String> accounts = List.of("SAV2001");
Iterator<String> it = accounts.iterator();
it.next();  // "SAV2001" (Recommended) 
it.next();  // NoSuchElementException! No more elements!

// FIX:
while (it.hasNext()) {
    String acc = it.next();  // safe — checked first!
}

// ═══ CAUSE 2: Optional.get() on empty ═══
Optional<String> empty = Optional.empty();
String value = empty.get();  // NoSuchElementException!

// FIX — NEVER use .get()! Use these instead:
String v1 = empty.orElse("DEFAULT");                          // fallback value
String v2 = empty.orElseGet(() -> loadDefault());             // lazy fallback
String v3 = empty.orElseThrow(() ->
    new TradeNotFoundException("TRD-999"));                    // explicit exception
empty.ifPresent(val -> process(val));                          // only if present
String v4 = empty.map(String::toUpperCase).orElse("N/A");    // transform + fallback

// ═══ CAUSE 3: Queue.remove() / Queue.element() on empty ═══
Queue<String> queue = new LinkedList<>();
queue.remove();   // NoSuchElementException! Empty queue!
queue.element();  // NoSuchElementException! Empty queue!

// FIX — use poll() / peek():
String polled = queue.poll();    // returns null if empty (no exception!)
String peeked = queue.peek();    // returns null if empty (no exception!)

// ═══ SUMMARY TABLE ═══
// THROWS NSEE:                  SAFE ALTERNATIVE:
// iterator.next()               → check hasNext() first
// optional.get()                → orElse / orElseThrow / ifPresent
// queue.remove()                → queue.poll() (returns null)
// queue.element()               → queue.peek() (returns null)
// stream.findFirst().get()      → findFirst().orElse(default)
