// ─── File: src/test/java/com/bank/nsee/NoSuchElementTest.java ───
package com.bank.nsee;

import org.junit.jupiter.api.Test;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class NoSuchElementTest {

    // ═══ Iterator: next() without hasNext() ═══
    @Test
    void iterator_nextWithoutHasNext() {
        List<String> trades = List.of("TRD-001");
        Iterator<String> it = trades.iterator();
        it.next();  // OK
        assertThatThrownBy(it::next)
            .isInstanceOf(NoSuchElementException.class);
    }

    @Test
    void iterator_safeWithHasNext() {
        List<String> trades = List.of("TRD-001", "TRD-002");
        Iterator<String> it = trades.iterator();
        List<String> result = new ArrayList<>();
        while (it.hasNext()) {
            result.add(it.next());  // safe!
        }
        assertThat(result).containsExactly("TRD-001", "TRD-002");
    }

    // ═══ Optional: get() on empty ═══
    @Test
    void optional_getOnEmpty() {
        Optional<String> empty = Optional.empty();
        assertThatThrownBy(empty::get)
            .isInstanceOf(NoSuchElementException.class);
    }

    @Test
    void optional_safeAlternatives() {
        Optional<String> empty = Optional.empty();
        Optional<String> present = Optional.of("SAV2001");

        // orElse: fallback value
        assertThat(empty.orElse("DEFAULT")).isEqualTo("DEFAULT");
        assertThat(present.orElse("DEFAULT")).isEqualTo("SAV2001");

        // orElseThrow: meaningful exception
        assertThatThrownBy(() ->
            empty.orElseThrow(() -> new RuntimeException("Trade not found")))
            .hasMessage("Trade not found");

        // map + orElse: transform safely
        assertThat(empty.map(String::toUpperCase).orElse("N/A")).isEqualTo("N/A");
        assertThat(present.map(String::toUpperCase).orElse("N/A")).isEqualTo("SAV2001");
    }

    // ═══ Queue: remove() vs poll() ═══
    @Test
    void queue_removeOnEmpty() {
        Queue<String> queue = new LinkedList<>();
        assertThatThrownBy(queue::remove)
            .isInstanceOf(NoSuchElementException.class);
    }

    @Test
    void queue_pollOnEmpty_returnsNull() {
        Queue<String> queue = new LinkedList<>();
        assertThat(queue.poll()).isNull();    // safe! No exception!
        assertThat(queue.peek()).isNull();    // safe! No exception!
    }

    @Test
    void queue_normalUsage() {
        Queue<String> queue = new LinkedList<>();
        queue.offer("TRD-001");
        queue.offer("TRD-002");

        assertThat(queue.poll()).isEqualTo("TRD-001");  // dequeues first
        assertThat(queue.poll()).isEqualTo("TRD-002");  // dequeues second
        assertThat(queue.poll()).isNull();                // empty → null (safe!)
    }
}
